<?php require 'core/Autoloader.php'; $db = \GM_HMS\Database\SecureDatabase::getInstance(); $admissions = $db->fetchAll('SELECT admission_id, patient_id FROM ipd_admissions'); $model = new \GM_HMS\Models\IpdBillingMaster(); foreach($admissions as $adm) { echo 'Testing ' . $adm['admission_id'] . PHP_EOL; $result = $model->getOrCreateForAdmission(['admission_id' => $adm['admission_id'], 'patient_id' => $adm['patient_id']]); $model->syncClinicalRecords($result['data']['bill_id'], $adm['admission_id'], 'system'); $model->getFullDetails($result['data']['bill_id']); echo 'Done ' . $adm['admission_id'] . PHP_EOL; }
